using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // A raw HTTP request is plain text: start line, headers, blank line, body.
        string raw = "POST /api/v1/orders?notify=true HTTP/1.1\r\n" +
                     "Host: api.example.com\r\n" +
                     "Content-Type: application/json\r\n" +
                     "Authorization: Bearer <token>\r\n" +
                     "\r\n" +
                     "{\"productId\":7,\"quantity\":2}";
        Console.WriteLine("Raw request:\n" + raw + "\n");

        // The blank line (\r\n\r\n) separates the head from the body.
        int split = raw.IndexOf("\r\n\r\n");
        string[] head = raw.Substring(0, split).Split(new[] { "\r\n" }, StringSplitOptions.None);
        string body = raw.Substring(split + 4);

        // Start line = method, target (path + query), protocol version.
        string[] start = head[0].Split(' ');
        string[] target = start[1].Split('?');

        // Every other head line is "Name: value". Header names ignore case.
        var headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        for (int i = 1; i < head.Length; i++)
        {
            int colon = head[i].IndexOf(':');
            headers[head[i].Substring(0, colon)] = head[i].Substring(colon + 1).Trim();
        }

        Console.WriteLine("Method : " + start[0]);
        Console.WriteLine("Path   : " + target[0]);
        Console.WriteLine("Query  : " + (target.Length > 1 ? target[1] : "(none)"));
        Console.WriteLine("Headers: " + headers.Count);
        Console.WriteLine("  content-type = " + headers["content-type"]);
        Console.WriteLine("Body   : " + body);
        // Time O(n) for n characters, space O(n) for the parsed parts.
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static Dictionary<int, string> orders = new Dictionary<int, string>();
    static int nextId = 1;

    // POST: the server picks a new id each time, so a repeat creates a second row.
    static int Post(string status) { int id = nextId++; orders[id] = status; return id; }

    // PUT: "make order {id} look like this". Repeating it changes nothing more.
    static void Put(int id, string status) { orders[id] = status; }

    // DELETE: the second call finds nothing, but the server state is the same.
    static int Delete(int id) { return orders.Remove(id) ? 204 : 404; }

    static void Main()
    {
        Console.WriteLine("PUT /orders/50 {shipped} sent twice (a retry)");
        Put(50, "shipped"); Put(50, "shipped");
        Console.WriteLine("  rows = " + orders.Count + "  -> idempotent");

        Console.WriteLine("POST /orders {new} sent twice (a retry)");
        Post("new"); Post("new");
        Console.WriteLine("  rows = " + orders.Count + "  -> NOT idempotent, a duplicate order exists");

        Console.WriteLine("DELETE /orders/50 sent twice");
        int first = Delete(50), second = Delete(50);
        Console.WriteLine("  status " + first + " then " + second + ", rows = " + orders.Count + "  -> idempotent");
        // Idempotent is about the state on the server, not about the status code.
        // Each call is O(1) time; the store uses O(n) space for n orders.
    }
}

using System;

class Program
{
    // Decide the status code in the same order the server checks things.
    static int Decide(bool hasValidToken, string role, bool orderExists, bool isOwner)
    {
        if (!hasValidToken) return 401;          // we do not know who you are
        if (role != "Customer") return 403;      // we know you, but you may not do this
        if (!orderExists || !isOwner) return 404; // hide other people's orders
        return 200;
    }

    static void Show(string caller, bool token, string role, bool exists, bool owner)
    {
        Console.WriteLine(caller.PadRight(34) + "-> " + Decide(token, role, exists, owner));
    }

    static void Main()
    {
        Console.WriteLine("GET /api/v1/orders/5");
        Show("no token or expired token", false, "", true, false);
        Show("valid token, role Guest", true, "Guest", true, false);
        Show("valid token, someone else's order", true, "Customer", true, false);
        Show("valid token, order does not exist", true, "Customer", false, false);
        Show("valid token, own order", true, "Customer", true, true);
        // 401 = authenticate first (send WWW-Authenticate). 403 = logging in again will not help.
        // Time O(1), space O(1).
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static string Show(Dictionary<string, object> d)
    {
        return "{" + string.Join(", ", d.OrderBy(p => p.Key).Select(p => p.Key + "=" + p.Value)) + "}";
    }

    // PUT: the body is the complete new resource. Anything left out is gone.
    static Dictionary<string, object> Put(Dictionary<string, object> current, Dictionary<string, object> body)
    {
        return new Dictionary<string, object>(body);
    }

    // PATCH (JSON Merge Patch, RFC 7396): copy only the fields sent; null means "remove".
    static Dictionary<string, object> Patch(Dictionary<string, object> current, Dictionary<string, object> body)
    {
        var result = new Dictionary<string, object>(current);
        foreach (var p in body)
        {
            if (p.Value == null) result.Remove(p.Key);
            else result[p.Key] = p.Value;
        }
        return result;
    }

    static void Main()
    {
        var order = new Dictionary<string, object> { { "status", "new" }, { "note", "leave at door" }, { "quantity", 2 } };
        var change = new Dictionary<string, object> { { "status", "shipped" } };
        var clear = new Dictionary<string, object> { { "note", null } };

        Console.WriteLine("Stored order        : " + Show(order));
        Console.WriteLine("PUT   {status}      : " + Show(Put(order, change)) + "   <- note and quantity lost");
        Console.WriteLine("PATCH {status}      : " + Show(Patch(order, change)));
        Console.WriteLine("PATCH {note: null}  : " + Show(Patch(order, clear)));
        // Time O(fields) per call, space O(fields) for the copy.
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static List<int> ids = Enumerable.Range(1, 10).ToList();   // order ids 1..10

    // Offset paging: skip N rows by position. The database still has to walk over them.
    static List<int> OffsetPage(int page, int size)
    {
        return ids.OrderByDescending(x => x).Skip((page - 1) * size).Take(size).ToList();
    }

    // Keyset paging: "rows after the last one I saw". An index can jump straight there.
    static List<int> KeysetPage(int? afterId, int size)
    {
        return ids.OrderByDescending(x => x).Where(x => afterId == null || x < afterId).Take(size).ToList();
    }

    static void Main()
    {
        Console.WriteLine("Orders 1..10, newest first, page size 3");
        var page1 = OffsetPage(1, 3);
        Console.WriteLine("Page 1          : " + string.Join(",", page1));

        ids.Add(11);   // a new order arrives while the user reads page 1
        Console.WriteLine("-- order 11 is created --");

        Console.WriteLine("Offset page 2   : " + string.Join(",", OffsetPage(2, 3)) + "   <- 8 shown twice");
        Console.WriteLine("Keyset after 8  : " + string.Join(",", KeysetPage(page1.Last(), 3)) + "   <- no repeat, no gap");
        // With a database index: offset costs O(offset + size) per page, keyset O(log n + size).
        // This in-memory demo sorts each time, O(n log n), only to keep it short.
    }
}

using System;

class NotFoundException : Exception { public NotFoundException(string m) : base(m) { } }
class ConflictException : Exception { public ConflictException(string m) : base(m) { } }

class Program
{
    // One place turns any exception into the same error shape (Problem Details, RFC 9457).
    static string ToProblem(Exception ex, string path, string traceId)
    {
        int status; string title; string detail = ex.Message;
        if (ex is NotFoundException) { status = 404; title = "Resource not found"; }
        else if (ex is ConflictException) { status = 409; title = "Conflict"; }
        else if (ex is ArgumentException) { status = 400; title = "Invalid request"; }
        else { status = 500; title = "Unexpected error"; detail = "Please quote the trace id."; }  // never leak internals

        return "HTTP " + status + "  Content-Type: application/problem+json\n" +
               "{ \"type\": \"https://example.com/problems/" + status + "\", \"title\": \"" + title + "\", \"status\": " + status +
               ", \"detail\": \"" + detail + "\", \"instance\": \"" + path + "\", \"traceId\": \"" + traceId + "\" }";
    }

    static void Main()
    {
        Exception[] thrown =
        {
            new NotFoundException("Order 99 does not exist."),
            new ConflictException("Order 5 is already shipped."),
            new ArgumentException("quantity must be at least 1."),
            new InvalidOperationException("SQL timeout on server db-07")   // internal detail, must be hidden
        };
        int n = 1;
        foreach (var ex in thrown)
        {
            Console.WriteLine("Thrown: " + ex.GetType().Name + " (" + ex.Message + ")");
            Console.WriteLine(ToProblem(ex, "/api/v1/orders/5", "trace-000" + n++) + "\n");
        }
        // Time O(1) per error, space O(1).
    }
}

using System;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static string product = "{\"id\":7,\"name\":\"Kettle\",\"price\":30}";

    // A strong ETag: a short fingerprint of the exact bytes of the response.
    static string ETag(string body)
    {
        using (var sha = SHA256.Create())
        {
            byte[] hash = sha.ComputeHash(Encoding.UTF8.GetBytes(body));
            return "\"" + BitConverter.ToString(hash, 0, 4).Replace("-", "").ToLower() + "\"";
        }
    }

    // Conditional GET: if the client's copy is still current, answer 304 with no body.
    static string Get(string ifNoneMatch)
    {
        string tag = ETag(product);
        if (ifNoneMatch == tag) return "304 Not Modified  ETag: " + tag + "  body: 0 bytes";
        return "200 OK  ETag: " + tag + "  Cache-Control: max-age=60  body: " + product.Length + " bytes";
    }

    static void Main()
    {
        Console.WriteLine("1. First GET (no cached copy)");
        Console.WriteLine("   " + Get(null));
        string cached = ETag(product);

        Console.WriteLine("2. GET with If-None-Match: " + cached);
        Console.WriteLine("   " + Get(cached));

        product = product.Replace("30", "35");   // the price changes on the server
        Console.WriteLine("3. Price changed, same If-None-Match");
        Console.WriteLine("   " + Get(cached));
        // Hashing is O(body size); the 304 saves bandwidth, not the server's work to build the body.
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static HashSet<string> allowedOrigins = new HashSet<string> { "https://app.example.com" };
    static HashSet<string> allowedMethods = new HashSet<string> { "GET", "POST", "PUT", "DELETE" };

    // "Simple" requests go straight out; everything else gets an OPTIONS preflight first.
    static bool NeedsPreflight(string method, string contentType, bool hasAuthorizationHeader)
    {
        bool simpleMethod = method == "GET" || method == "HEAD" || method == "POST";
        bool simpleType = contentType == null || contentType == "text/plain" ||
                          contentType == "application/x-www-form-urlencoded" || contentType == "multipart/form-data";
        return !simpleMethod || !simpleType || hasAuthorizationHeader;
    }

    // The server's answer to the preflight. No Allow-Origin header = the browser blocks the call.
    static string Preflight(string origin, string method)
    {
        if (!allowedOrigins.Contains(origin) || !allowedMethods.Contains(method))
            return "204 with no CORS headers -> browser blocks the request";
        return "204 Access-Control-Allow-Origin: " + origin + ", Allow-Methods: " + method + ", Max-Age: 600";
    }

    static void Main()
    {
        Console.WriteLine("Allowed origins: " + string.Join(", ", allowedOrigins));
        Console.WriteLine("GET, no custom headers          preflight? " + NeedsPreflight("GET", null, false));
        Console.WriteLine("POST application/json           preflight? " + NeedsPreflight("POST", "application/json", false));
        Console.WriteLine("GET with Authorization header   preflight? " + NeedsPreflight("GET", null, true));
        Console.WriteLine("DELETE                          preflight? " + NeedsPreflight("DELETE", null, false));
        Console.WriteLine();
        Console.WriteLine("OPTIONS from https://app.example.com for PUT:");
        Console.WriteLine("  " + Preflight("https://app.example.com", "PUT"));
        Console.WriteLine("OPTIONS from https://evil.example.net for PUT:");
        Console.WriteLine("  " + Preflight("https://evil.example.net", "PUT"));
        // Set lookups are O(1) time; space is O(number of allowed origins).
    }
}

using System;

// Token bucket: holds up to `capacity` tokens and gains `refillPerSecond` tokens each second.
class TokenBucket
{
    readonly int capacity, refillPerSecond;
    int tokens, lastSecond;

    public TokenBucket(int capacity, int refillPerSecond)
    {
        this.capacity = capacity; this.refillPerSecond = refillPerSecond; tokens = capacity;
    }

    // Returns 200 if a token was available, otherwise 429.
    public int TryRequest(int nowSecond)
    {
        // Top up for the time that passed, but never above the capacity (this allows a small burst).
        tokens = Math.Min(capacity, tokens + (nowSecond - lastSecond) * refillPerSecond);
        lastSecond = nowSecond;
        if (tokens == 0) return 429;
        tokens--;
        return 200;
    }
}

class Program
{
    static void Main()
    {
        var bucket = new TokenBucket(3, 1);
        int[] arrivals = { 0, 0, 0, 0, 1, 3, 3, 3, 3 };   // the second each request arrives
        Console.WriteLine("Bucket: capacity 3, refill 1 token per second");
        foreach (int t in arrivals)
        {
            int status = bucket.TryRequest(t);
            // A 429 should tell the client when to come back.
            Console.WriteLine("t=" + t + "s -> " + status + (status == 429 ? "  Retry-After: 1" : ""));
        }
        // Time O(1) per request, space O(1) per client key (user id, API key or IP).
    }
}

using System;
using System.Collections.Generic;

class Result
{
    public int Status; public string Extra;
    public Result(int status, string extra) { Status = status; Extra = extra; }
    public override string ToString() { return Status + (Extra == null ? "" : "  " + Extra); }
}

// A model of a CRUD controller: each method maps one HTTP verb to one status code.
class OrdersController
{
    readonly Dictionary<int, string> db = new Dictionary<int, string>();
    int nextId = 1;

    public Result Get(int id) { return db.ContainsKey(id) ? new Result(200, "body: " + db[id]) : new Result(404, null); }

    public Result Post(string product)
    {
        if (string.IsNullOrWhiteSpace(product)) return new Result(400, "product is required");   // validate first
        int id = nextId++; db[id] = product;
        return new Result(201, "Location: /api/v1/orders/" + id);   // 201 always points at the new resource
    }

    public Result Put(int id, string product)
    {
        if (!db.ContainsKey(id)) return new Result(404, null);
        db[id] = product;
        return new Result(204, null);   // success, nothing to send back
    }

    public Result Delete(int id) { return db.Remove(id) ? new Result(204, null) : new Result(404, null); }
}

class Program
{
    static void Main()
    {
        var c = new OrdersController();
        Console.WriteLine("POST   /orders {kettle}  -> " + c.Post("kettle"));
        Console.WriteLine("POST   /orders {}        -> " + c.Post(""));
        Console.WriteLine("GET    /orders/1         -> " + c.Get(1));
        Console.WriteLine("GET    /orders/99        -> " + c.Get(99));
        Console.WriteLine("PUT    /orders/1 {mug}   -> " + c.Put(1, "mug"));
        Console.WriteLine("GET    /orders/1         -> " + c.Get(1));
        Console.WriteLine("DELETE /orders/1         -> " + c.Delete(1));
        Console.WriteLine("DELETE /orders/1         -> " + c.Delete(1));
        // Every action is O(1) time on a dictionary; space O(n) for n orders.
    }
}

using System;
using System.Collections.Generic;

// A tiny model of minimal APIs: a route group adds a prefix and filters to every endpoint in it.
class RouteGroup
{
    readonly string prefix;
    readonly Dictionary<string, Func<string, string>> routes;
    readonly List<Func<Func<string, string>, Func<string, string>>> filters = new List<Func<Func<string, string>, Func<string, string>>>();

    public RouteGroup(string prefix, Dictionary<string, Func<string, string>> routes) { this.prefix = prefix; this.routes = routes; }

    // An endpoint filter wraps the handler: it can stop the call or run code before and after it.
    public RouteGroup AddFilter(Func<Func<string, string>, Func<string, string>> filter) { filters.Add(filter); return this; }

    public void Map(string method, string pattern, Func<string, string> handler)
    {
        for (int i = filters.Count - 1; i >= 0; i--) handler = filters[i](handler);   // first filter added runs first
        routes[method + " " + prefix + pattern] = handler;
    }
}

class Program
{
    static void Main()
    {
        var routes = new Dictionary<string, Func<string, string>>();
        var orders = new RouteGroup("/api/v1/orders", routes)
            .AddFilter(next => body => { Console.WriteLine("  [log] handling request"); return next(body); })
            .AddFilter(next => body => body == "" ? "400 quantity is required" : next(body));   // validation filter

        orders.Map("GET", "/5", body => "200 {\"id\":5}");
        orders.Map("POST", "", body => "201 Location: /api/v1/orders/6");

        string[][] calls = { new[] { "GET /api/v1/orders/5", "-" }, new[] { "POST /api/v1/orders", "{\"quantity\":2}" },
                             new[] { "POST /api/v1/orders", "" }, new[] { "GET /api/v2/orders", "-" } };
        foreach (var call in calls)
        {
            Console.WriteLine(call[0] + "  body: '" + call[1] + "'");
            Func<string, string> handler;
            Console.WriteLine("  -> " + (routes.TryGetValue(call[0], out handler) ? handler(call[1]) : "404 no such route"));
        }
        // Route lookup is O(1); each request passes through O(filters) wrappers.
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

class Program
{
    static string[] supported = { "application/json", "text/csv" };   // first one is the default

    // Pick the response format from the Accept header. q is the client's preference from 0 to 1.
    static string Negotiate(string accept)
    {
        if (string.IsNullOrEmpty(accept)) return "200 " + supported[0];
        var wanted = new List<KeyValuePair<string, double>>();
        foreach (string part in accept.Split(','))
        {
            string[] bits = part.Trim().Split(';');
            double q = 1.0;   // no q given means "most preferred"
            foreach (string b in bits.Skip(1))
                if (b.Trim().StartsWith("q=")) q = double.Parse(b.Trim().Substring(2), CultureInfo.InvariantCulture);
            wanted.Add(new KeyValuePair<string, double>(bits[0].Trim(), q));
        }
        // Try the client's choices from highest q to lowest.
        foreach (var w in wanted.OrderByDescending(x => x.Value))
        {
            if (w.Key == "*/*") return "200 " + supported[0];
            if (supported.Contains(w.Key)) return "200 " + w.Key;
        }
        return "406 Not Acceptable";   // we cannot produce anything the client asked for
    }

    static void Main()
    {
        Console.WriteLine("Server can produce: " + string.Join(", ", supported));
        string[] headers = { "application/json", "text/csv;q=0.9, application/json;q=0.5",
                             "application/xml, text/csv;q=0.4", "application/xml", "*/*", "" };
        foreach (string h in headers)
            Console.WriteLine("Accept: " + (h == "" ? "(missing)" : h).PadRight(40) + "-> " + Negotiate(h) + "  Vary: Accept");
        // Time O(k log k) for k media types in the header, space O(k).
    }
}

using System;

class Program
{
    static string address = "1 Old Road";
    static int version = 1;                       // in SQL Server this would be a rowversion column

    static string ETag() { return "\"v" + version + "\""; }

    // The update succeeds only if the caller proves it saw the latest version.
    static string Put(string who, string ifMatch, string newAddress)
    {
        string result;
        if (ifMatch == null) result = "428 Precondition Required (send If-Match)";
        else if (ifMatch != ETag()) result = "412 Precondition Failed (someone changed it; current ETag " + ETag() + ")";
        else
        {
            address = newAddress; version++;      // one atomic step in a real database
            result = "200 OK, new ETag " + ETag();
        }
        return who + " PUT If-Match: " + (ifMatch ?? "(none)") + " -> " + result;
    }

    static void Main()
    {
        // Two users open the same order at the same time and both read version 1.
        string annTag = ETag(), bobTag = ETag();
        Console.WriteLine("Ann and Bob both GET the order: address '" + address + "', ETag " + annTag);

        Console.WriteLine(Put("Ann", annTag, "2 New Street"));
        Console.WriteLine(Put("Bob", bobTag, "3 Other Lane"));   // Bob's copy is stale: no silent overwrite
        Console.WriteLine(Put("Bob", null, "3 Other Lane"));

        // Bob reloads, sees Ann's change, and tries again with the fresh ETag.
        Console.WriteLine(Put("Bob", ETag(), "3 Other Lane"));
        Console.WriteLine("Final address: '" + address + "', ETag " + ETag());
        // Time O(1) per update, space O(1): no locks are held between requests.
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // key -> the request body we saw and the response we gave the first time
    static Dictionary<string, string[]> seen = new Dictionary<string, string[]>();
    static int charges = 0;

    static string Pay(string idempotencyKey, string body)
    {
        string[] saved;
        if (seen.TryGetValue(idempotencyKey, out saved))
        {
            // Same key with a different body is a client bug: refuse instead of guessing.
            if (saved[0] != body) return "422 key was already used with a different request";
            return saved[1] + "  (replayed, card not charged again)";
        }
        charges++;                                   // the real work happens exactly once
        string response = "201 Created payment " + charges;
        seen[idempotencyKey] = new[] { body, response };   // in production: same transaction as the charge
        return response;
    }

    static void Main()
    {
        Console.WriteLine("POST /payments  key=A  {amount:50}  -> " + Pay("A", "{amount:50}"));
        Console.WriteLine("  (the response is lost on the network, so the client retries)");
        Console.WriteLine("POST /payments  key=A  {amount:50}  -> " + Pay("A", "{amount:50}"));
        Console.WriteLine("POST /payments  key=A  {amount:99}  -> " + Pay("A", "{amount:99}"));
        Console.WriteLine("POST /payments  key=B  {amount:50}  -> " + Pay("B", "{amount:50}"));
        Console.WriteLine("Charges made: " + charges + " for 4 requests");
        // Time O(1) per request; space O(keys kept), so expire keys after about 24 hours.
    }
}

using System;
using System.Collections.Generic;

class Job { public string State = "Queued"; public int Percent; public string Result; }

class Program
{
    static Dictionary<int, Job> jobs = new Dictionary<int, Job>();
    static int nextId = 123;

    // The API does no heavy work: it records the job and answers at once.
    static string Submit()
    {
        int id = nextId++; jobs[id] = new Job();
        return "202 Accepted  Location: /imports/jobs/" + id + "  Retry-After: 5";
    }

    // A background worker moves the job forward one step at a time.
    static void WorkerStep(int id)
    {
        Job j = jobs[id];
        j.State = "Running"; j.Percent += 50;
        if (j.Percent >= 100) { j.State = "Succeeded"; j.Result = "/imports/123/report"; }
    }

    // The status endpoint is a cheap read the client can poll.
    static string Status(int id)
    {
        Job j;
        if (!jobs.TryGetValue(id, out j)) return "404 Not Found";
        if (j.State == "Succeeded") return "200 { state: Succeeded, result: " + j.Result + " }";
        return "200 { state: " + j.State + ", percent: " + j.Percent + " }  Retry-After: 5";
    }

    static void Main()
    {
        Console.WriteLine("POST /imports (a file with 1,000,000 rows)");
        Console.WriteLine("  " + Submit());
        Console.WriteLine("GET /imports/jobs/123 -> " + Status(123));
        WorkerStep(123);
        Console.WriteLine("GET /imports/jobs/123 -> " + Status(123));
        WorkerStep(123);
        Console.WriteLine("GET /imports/jobs/123 -> " + Status(123));
        Console.WriteLine("GET /imports/jobs/999 -> " + Status(999));
        // Submit and Status are O(1); the long work runs outside the request.
    }
}

using System;

class Program
{
    static int callsToDependency = 0, failuresLeft;

    // The remote service: fails while failuresLeft > 0.
    static string CallRates()
    {
        callsToDependency++;
        if (failuresLeft > 0) { failuresLeft--; throw new Exception("503 from rates service"); }
        return "200 rate=1.08";
    }

    // Circuit breaker state: after 3 failures in a row, stop calling for a while.
    static int consecutiveFailures = 0;
    static bool open = false;

    static string GetWithResilience()
    {
        if (open) return "failed fast: circuit is open (dependency not called)";
        int delayMs = 200;
        for (int attempt = 1; attempt <= 3; attempt++)
        {
            try { string r = CallRates(); consecutiveFailures = 0; return r + " on attempt " + attempt; }
            catch (Exception ex)
            {
                consecutiveFailures++;
                Console.WriteLine("    attempt " + attempt + " failed (" + ex.Message + ")");
                if (consecutiveFailures >= 3) { open = true; return "gave up: circuit opened"; }
                if (attempt < 3) Console.WriteLine("    wait " + delayMs + " ms plus random jitter");
                delayMs *= 2;   // exponential backoff: 200, 400, 800...
            }
        }
        return "gave up after 3 attempts";
    }

    static void Main()
    {
        failuresLeft = 2;
        Console.WriteLine("Call 1: dependency fails twice, then recovers");
        Console.WriteLine("  -> " + GetWithResilience());
        failuresLeft = 100;
        Console.WriteLine("Call 2: dependency is down");
        Console.WriteLine("  -> " + GetWithResilience());
        Console.WriteLine("Call 3: still down");
        Console.WriteLine("  -> " + GetWithResilience());
        Console.WriteLine("Calls that reached the dependency: " + callsToDependency);
        // Time O(attempts) per call, space O(1). Retry only idempotent calls.
    }
}

