class Order { public int Id; public string OwnerId; public string Address; public bool IsPaid; }
class UpdateOrderDto { public string Address; }   // the only field a client may change

class Program
{
    static Dictionary<int, Order> db = new Dictionary<int, Order>
    {
        { 1, new Order { Id = 1, OwnerId = "alice", Address = "1 Old Road" } },
        { 2, new Order { Id = 2, OwnerId = "bob", Address = "9 Hill Street" } }
    };

    // BOLA bug: any logged-in user can read any id just by changing the number in the URL.
    static string GetUnsafe(string caller, int id) { return db.ContainsKey(id) ? "200 " + db[id].Address : "404"; }

    // Fix: the lookup itself includes the owner, so a foreign order looks like a missing one.
    static string GetSafe(string caller, int id)
    {
