        return db.TryGetValue(id, out o) && o.OwnerId == caller ? "200 " + o.Address : "404";
    }

    // Mass assignment fix: bind to a small DTO and copy field by field. IsPaid can never be set here.
    static void Update(Order o, UpdateOrderDto dto) { o.Address = dto.Address; }

    static void Main()
    {
        Console.WriteLine("alice calls GET /orders/2 (bob's order)");
        Console.WriteLine("  without owner check: " + GetUnsafe("alice", 2) + "   <- data leak (BOLA)");
        Console.WriteLine("  with owner check   : " + GetSafe("alice", 2));
        Console.WriteLine("alice calls GET /orders/1 (her own): " + GetSafe("alice", 1));

        Console.WriteLine("alice sends PATCH /orders/1 {\"address\":\"2 New Street\",\"isPaid\":true}");
