using System;
using System.Collections.Generic;
using System.Text;

class Program
{
    // Varint: 7 bits of the number per byte; the top bit says "more bytes follow".
    static void WriteVarint(List<byte> output, ulong value)
    {
        while (value >= 0x80) { output.Add((byte)(value | 0x80)); value >>= 7; }
        output.Add((byte)value);
    }

    // A protobuf field is a tag (field number and wire type) followed by the value. No field names.
    static void WriteIntField(List<byte> output, int fieldNumber, ulong value)
    {
        WriteVarint(output, (ulong)(fieldNumber << 3));   // wire type 0 = varint
        WriteVarint(output, value);
    }

    static void Main()
    {
        // message PriceRequest { int32 product_id = 1; int32 quantity = 2; }
        int productId = 150, quantity = 2;
        var bytes = new List<byte>();
        WriteIntField(bytes, 1, (ulong)productId);
        WriteIntField(bytes, 2, (ulong)quantity);

        string json = "{\"productId\":" + productId + ",\"quantity\":" + quantity + "}";

        Console.WriteLine("Message: productId=150, quantity=2");
        Console.WriteLine("JSON     : " + json + "  = " + Encoding.UTF8.GetByteCount(json) + " bytes");
        Console.WriteLine("Protobuf : " + BitConverter.ToString(bytes.ToArray()).Replace("-", " ") + "  = " + bytes.Count + " bytes");
        Console.WriteLine("08 = field 1, 96 01 = 150 as a varint, 10 = field 2, 02 = 2");
        // Time O(bytes written), space O(bytes written).
    }
}

