    // The "server" method. It passes the token on, so it stops when the deadline passes.
    static async Task<string> GetPrice(int workMs, CancellationToken token)
    {
        await Task.Delay(workMs, token);
        return "price=30";
    }

    // The client sets one time limit for the whole call, like a gRPC deadline.
    static string CallWithDeadline(int workMs, int deadlineMs)
    {
        using (var cts = new CancellationTokenSource(deadlineMs))
        {
            try { return "OK " + GetPrice(workMs, cts.Token).GetAwaiter().GetResult(); }
            catch (OperationCanceledException) { return "DEADLINE_EXCEEDED (server work was cancelled)"; }
        }
    }

    // Server streaming: one request, many replies, sent one at a time.
    static IEnumerable<string> WatchPrices()
    {
        yield return "price=30";
        yield return "price=31";
        yield return "price=29";
    }

    static void Main()
    {
        Console.WriteLine("Unary call, work 10 ms, deadline 2000 ms -> " + CallWithDeadline(10, 2000));
        Console.WriteLine("Unary call, work 5000 ms, deadline 100 ms -> " + CallWithDeadline(5000, 100));
        Console.WriteLine("Server streaming call:");
        foreach (string message in WatchPrices()) Console.WriteLine("  received " + message);
        // The slow call returns after about 100 ms, not 5000: nobody waits for work no one wants.
    }
}

