using System.Collections.Generic;

class Program
{
    // On the wire a protobuf message is just (field number -> value). Names are not sent.
    static string OldReader(Dictionary<int, string> wire)
    {
        // Version 1 of the contract knows only fields 1 and 2.
        string id = wire.ContainsKey(1) ? wire[1] : "0";
        string amount = wire.ContainsKey(2) ? wire[2] : "0";
        int unknown = 0;
        foreach (int number in wire.Keys) if (number != 1 && number != 2) unknown++;   // skipped, not an error
        return "product_id=" + id + ", amount=" + amount + ", unknown fields skipped=" + unknown;
    }

    static string NewReader(Dictionary<int, string> wire)
    {
        // Version 2 added "currency = 4". A missing field reads as its default value.
        string currency = wire.ContainsKey(4) ? wire[4] : "(default: empty)";
        return "product_id=" + wire[1] + ", amount=" + wire[2] + ", currency=" + currency;
    }

    static void Main()
    {
        var fromNewServer = new Dictionary<int, string> { { 1, "7" }, { 2, "30" }, { 4, "EUR" } };
        var fromOldServer = new Dictionary<int, string> { { 1, "7" }, { 2, "30" } };

        Console.WriteLine("Safe change: add field 4 (currency)");
        Console.WriteLine("  old client reads new message: " + OldReader(fromNewServer));
        Console.WriteLine("  new client reads old message: " + NewReader(fromOldServer));

        // Unsafe: field 2 used to be "amount"; someone reuses number 2 for "quantity".
        var reused = new Dictionary<int, string> { { 1, "7" }, { 2, "500" } };
        Console.WriteLine("Unsafe change: reuse number 2 for quantity=500");
        Console.WriteLine("  old client reads it as      : " + OldReader(reused) + "   <- wrong price, no error");
        // Time O(fields) per message, space O(fields).
    }
}

