const customers = { 10: "Ann", 20: "Bob", 30: "Cy" };
let dbCalls = 0;

// The "database": one call per invocation, however many ids it carries.
async function loadCustomers(ids) {
  dbCalls++;
  return ids.map((id) => customers[id]);
}

// A minimal DataLoader: collect the keys asked for in this tick, then load them in ONE call.
function createLoader(batchFn) {
  const cache = new Map();   // key -> promise, so the same key is asked for only once
  let queue = [];
  return (key) => {
    if (cache.has(key)) return cache.get(key);
    const promise = new Promise((resolve) => {
      if (queue.length === 0) {
        // Run after every resolver in this tick has had its chance to add a key.
        process.nextTick(async () => {
          const batch = queue; queue = [];
          const values = await batchFn(batch.map((b) => b.key));
          batch.forEach((b, i) => b.resolve(values[i]));
        });
      }
      queue.push({ key, resolve });
    });
    cache.set(key, promise);
    return promise;
  };
}

