// A query as a tree: each field has a name, an optional page size, and child fields.
const cheap = { name: "orders", first: 20, children: [{ name: "id" }, { name: "total" }] };
const expensive = {
  name: "orders", first: 100, children: [
    { name: "id" },
    { name: "customer", children: [
      { name: "orders", first: 100, children: [
        { name: "items", first: 50, children: [{ name: "title" }] }
      ] }
    ] }
  ]
};

// Depth: how many levels of nesting the query has.
function depth(field) {
  if (!field.children) return 1;
  return 1 + Math.max(...field.children.map(depth));
}

// Cost: 1 per field, and a list multiplies the cost of everything under it by its page size.
function cost(field) {
  const childCost = (field.children || []).reduce((sum, c) => sum + cost(c), 0);
  return 1 + (field.first || 1) * childCost;
}

const MAX_DEPTH = 4, MAX_COST = 1000;

// Checked BEFORE any resolver runs, so a hostile query costs the server almost nothing.
function check(name, query) {
  const d = depth(query), c = cost(query);
  const verdict = d > MAX_DEPTH ? "REJECTED (too deep)" : c > MAX_COST ? "REJECTED (too costly)" : "allowed";
  console.log(name + ": depth " + d + ", cost " + c + " -> " + verdict);
}

console.log("Limits: depth <= " + MAX_DEPTH + ", cost <= " + MAX_COST);
check("orders(first:20){id total}                      ", cheap);
check("orders(100){id customer{orders(100){items(50)}}}", expensive);
// Time O(fields in the query), space O(depth) for the recursion.

