using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static byte[] secret = Encoding.UTF8.GetBytes("demo-shared-secret-not-real");
    static HashSet<string> processedEvents = new HashSet<string>();

    // The sender signs "timestamp.rawBody" with the shared secret.
    static string Sign(long timestamp, string rawBody)
    {
        using (var hmac = new HMACSHA256(secret))
            return BitConverter.ToString(hmac.ComputeHash(Encoding.UTF8.GetBytes(timestamp + "." + rawBody))).Replace("-", "").ToLower();
    }

    // Compare every character even after a mismatch, so timing reveals nothing.
    static bool ConstantTimeEquals(string a, string b)
    {
        if (a.Length != b.Length) return false;
        int diff = 0;
        for (int i = 0; i < a.Length; i++) diff |= a[i] ^ b[i];
        return diff == 0;
    }

    static string Receive(string eventId, long timestamp, string rawBody, string signature, long now)
    {
        if (!ConstantTimeEquals(Sign(timestamp, rawBody), signature)) return "401 bad signature";
        if (now - timestamp > 300) return "400 too old (possible replay)";          // 5 minute window
        if (!processedEvents.Add(eventId)) return "200 duplicate, already handled";   // senders retry
        return "200 accepted, queued for processing";
    }

    static void Main()
    {
        long now = 1000000;
        string body = "{\"event\":\"order.paid\",\"orderId\":5}";
        string sig = Sign(now, body);
        Console.WriteLine("Body: " + body);
        Console.WriteLine("genuine event          -> " + Receive("evt_1", now, body, sig, now));
        Console.WriteLine("same event sent again  -> " + Receive("evt_1", now, body, sig, now + 10));
        Console.WriteLine("body changed in transit -> " + Receive("evt_2", now, body.Replace("5", "6"), sig, now));
        Console.WriteLine("replayed an hour later -> " + Receive("evt_3", now, body, sig, now + 3600));
        // Time O(body size) for the HMAC; space O(event ids remembered).
    }
}

