            Console.WriteLine((r.Value != null ? "OK   " : "GAP  ") + r.Key.PadRight(32) + (r.Value ?? "no authorization declared"));
        // Time O(cases + routes), space O(1).
    }
}

using System;

// The code asks an interface for the time, never DateTime.UtcNow directly.
interface IClock { DateTime UtcNow { get; } }

// The test owns this clock and moves it forward by hand: no waiting, no flakiness.
class FakeClock : IClock
{
    public DateTime UtcNow { get; private set; }
    public FakeClock(DateTime start) { UtcNow = start; }
    public void Advance(TimeSpan by) { UtcNow = UtcNow.Add(by); }
}

class Token
{
    readonly DateTime expiresAt; readonly IClock clock;
    public Token(IClock clock, TimeSpan lifetime) { this.clock = clock; expiresAt = clock.UtcNow.Add(lifetime); }
    public bool IsExpired { get { return clock.UtcNow >= expiresAt; } }
}

class Program
{
    static void Check(string name, bool ok) { Console.WriteLine((ok ? "PASS " : "FAIL ") + name); }

    static void Main()
    {
        // A fixed start time: the test gives the same result on any day and any machine.
        var clock = new FakeClock(new DateTime(2026, 1, 1, 12, 0, 0, DateTimeKind.Utc));
        var token = new Token(clock, TimeSpan.FromMinutes(60));
        Console.WriteLine("Token created at " + clock.UtcNow.ToString("HH:mm") + " with a 60 minute lifetime");

        Check("valid when just created", !token.IsExpired);
        clock.Advance(TimeSpan.FromMinutes(59));
        Check("still valid at " + clock.UtcNow.ToString("HH:mm"), !token.IsExpired);
        clock.Advance(TimeSpan.FromMinutes(1));
        Check("expired at " + clock.UtcNow.ToString("HH:mm") + " (exact boundary)", token.IsExpired);
        // The test covers an hour of "time" in microseconds: O(1) time and space, no Thread.Sleep.
    }
}
